/** One required-claim constraint, JSON-encoded for type-flexible matching. */
export interface PlaybackJwtClaimRequirement {
    name: Scalars['String']
    /** JSON-encoded expected value (e.g. `"pro"`, `true`, `42`, `["a","b"]`). */
    jsonValue: Scalars['String']
    __typename: 'PlaybackJwtClaimRequirement'
}


/**
 * JWT-gated playback policy. The viewer attaches a JWT minted with one of the
 * allowed signing keys; FrameWorks verifies signature, alg=ES256, exp/iat/nbf,
 * and any required audience / claim constraints.
 */
export interface PlaybackJwtPolicy {
    /** Allowed signing key IDs. Empty = any active tenant key. */
    allowedKids: Scalars['String'][]
    /** If set, the viewer JWT's `aud` claim must contain at least one of these. */
    requiredAudience: Scalars['String'][]
    /**
     * Required claim constraints. Each value is the JSON-encoded representation
     * of the expected claim value (so callers can require strings, numbers,
     * booleans, or arrays consistently). Empty = no claim check.
     */
    requiredClaimsJson: PlaybackJwtClaimRequirement[]
    __typename: 'PlaybackJwtPolicy'
}

