/**
 * A live stream configuration with real-time operational metrics.
 * Streams are the core entity for broadcasting and viewing live content.
 */
export interface Stream {
    /** Global unique identifier for Relay compatibility. */
    id: Scalars['ID']
    /** Public stream UUID used for analytics and service APIs (not the Relay ID). */
    streamId: Scalars['String']
    /** Human-readable display name for the stream. */
    name: Scalars['String']
    /** Optional description for the stream. */
    description: (Scalars['String'] | null)
    /** Secret key for publisher-authenticated ingest; null for pull and managed sources. */
    streamKey: (Scalars['String'] | null)
    /** Public identifier for playback URLs. */
    playbackId: Scalars['String']
    /** Whether DVR recording is enabled for this stream. */
    record: Scalars['Boolean']
    /** How source media enters the stream. */
    ingestMode: IngestMode
    /** Pull-source config for pull streams; null for push streams. */
    pullSource: (PullSourceView | null)
    /** Safe source summary for managed streams; null for push and pull streams. */
    managedSource: (ManagedSourceView | null)
    /** Where the stream's source may be ingested, derived from the stream's own ingest placement rules. */
    sourceLocation: SourceLocation
    /** When this stream was created. */
    createdAt: Scalars['Time']
    /** When this stream was last modified. */
    updatedAt: Scalars['Time']
    /**
     * Real-time operational metrics from the data plane.
     * Includes viewer counts, quality metrics, and throughput data.
     * Lazily loaded from ClickHouse analytics.
     */
    metrics: (StreamMetrics | null)
    /** Configured multistream push targets for this stream. */
    pushTargets: PushTarget[]
    /** Playback access policy. null/PUBLIC = anyone with the playbackId can watch. */
    playbackPolicy: (PlaybackPolicy | null)
    /**
     * DVR chapter rotation mode. Snapshotted onto the DVR artifact at StartDVR;
     * changes take effect on the next recording. null/NONE = chapters disabled.
     */
    dvrChapterMode: (DVRChapterMode | null)
    /**
     * Chapter interval in seconds. Required when dvrChapterMode = FIXED_INTERVAL,
     * ignored otherwise. Minimum 3600 (1 hour).
     */
    dvrChapterIntervalSeconds: (Scalars['Int'] | null)
    /** Per-stream Skipper monitoring override (INHERIT follows tier). */
    monitoring: MonitoringToggle
    /**
     * Recent pull-source resolution events for pull streams. Captures the
     * customer-facing resolution outcome (resolved, not_found, disabled,
     * blocked_uri, cluster_not_allowed_delegate, commodore_error,
     * foghorn_base_unresolved). Null for push streams.
     */
    recentPullSourceEvents: (PullSourceEvent[] | null)
    /**
     * Server-resolved Chandler URLs for the stream's poster and sprite
     * thumbnails. Derived from active_ingest_cluster_id + stream_id at SELECT
     * time. Null when the stream has never been live; the poster.jpg 404s
     * until Helmsman uploads its first frame, which the player's fallback
     * chain handles.
     */
    thumbnailAssets: (ThumbnailAssets | null)
    /**
     * Per-stream retention overrides for DVR and clips. Null when the stream
     * has no overrides set (inherits the tenant default). VOD uploads aren't
     * stream-bound, so they don't appear here.
     */
    retentionOverrides: (StreamRetentionOverrides | null)
    __typename: 'Stream'
}

