    /** Primary video track height in pixels. */
    primaryHeight: (Scalars['Int'] | null)
    /** Primary video track framerate. */
    primaryFps: (Scalars['Float'] | null)
    /** Primary video codec (H.264, H.265, VP9, AV1). */
    primaryCodec: (Scalars['String'] | null)
